<?php $rows = ClientApi::data($api->request('GET','api/reservations')); ?>
<section class="panel"><div class="notice"><b>Les paiements en ligne ne sont pas encore intégrés.</b><br>Les montants ci-dessous sont les montants associés à vos réservations; ils ne constituent pas une confirmation de paiement. Aucun reçu ou transaction n’est affiché sans enregistrement réel.</div><h2 class="section-title" style="margin-top:22px">Montants liés aux réservations</h2><?php if (!$rows): ?><div class="empty"><h3>Aucun montant enregistré</h3><p>Une réservation avec un tarif défini apparaîtra ici.</p></div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Référence</th><th>Voyage</th><th>Date</th><th>Montant enregistré</th><th>État</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><?= client_h($r['reference'] ?? '') ?></td><td><?= client_h($r['libelle_snapshot'] ?? '—') ?></td><td><?= client_h(client_format_date($r['created_at'] ?? null)) ?></td><td><?= client_money($r['montant_total'] ?? null,$r['devise'] ?? null) ?></td><td><?= client_h(($r['statut'] ?? '') === 'annulee' ? 'Réservation annulée' : 'Paiement non disponible') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
